int prim(int n, vector<vector<pair<int,int>>>& adj) {   // adj[u] = list of {v, weight}
    vector<bool> inMST(n, false);
    priority_queue<pair<int,int>, vector<pair<int,int>>, greater<>> pq;   // {weight, node}
    pq.push({0, 0});
    int total = 0, count = 0;
    while (!pq.empty() && count < n) {
        auto [w, u] = pq.top(); pq.pop();
        if (inMST[u]) continue;             // stale entry, skip
        inMST[u] = true; total += w; count++;
        for (auto [v, wt] : adj[u])
            if (!inMST[v]) pq.push({wt, v});
    }
    return total;
}

