import heapq
def prim(n, adj):                      # adj[u] = list of (v, weight)
    in_mst = [False] * n
    pq = [(0, 0)]                       # (weight, node)
    total = count = 0
    while pq and count < n:
        w, u = heapq.heappop(pq)
        if in_mst[u]:
            continue                    # stale entry, skip
        in_mst[u] = True
        total += w
        count += 1
        for v, wt in adj[u]:
            if not in_mst[v]:
                heapq.heappush(pq, (wt, v))
    return total

