int prim(int n, List<int[]>[] adj) {   // adj[u] = list of {v, weight}
    boolean[] inMST = new boolean[n];
    PriorityQueue<int[]> pq = new PriorityQueue<>((a, b) -> a[0] - b[0]);   // {weight, node}
    pq.add(new int[]{0, 0});
    int total = 0, count = 0;
    while (!pq.isEmpty() && count < n) {
        int[] top = pq.poll();
        int w = top[0], u = top[1];
        if (inMST[u]) continue;         // stale entry, skip
        inMST[u] = true; total += w; count++;
        for (int[] e : adj[u])
            if (!inMST[e[0]]) pq.add(new int[]{e[1], e[0]});
    }
    return total;
}

