function prim(n, adj) {                // adj[u] = array of [v, weight]; uses a min-heap
  const inMST = new Array(n).fill(false);
  const pq = new MinHeap();             // ordered by weight
  pq.push([0, 0]);                      // [weight, node]
  let total = 0, count = 0;
  while (pq.size() && count < n) {
    const [w, u] = pq.pop();
    if (inMST[u]) continue;             // stale entry, skip
    inMST[u] = true; total += w; count++;
    for (const [v, wt] of adj[u])
      if (!inMST[v]) pq.push([wt, v]);
  }
  return total;
}
